\begin{equation}\label{2.27}
	\bar{\mathfrak{E}_{\theta}}:={\rm e}^{2\delta_0\kappa t}\mathcal{E}_{\theta,0}+\mathcal{E}_{\theta,\neq}+\frac{1}{2^{12}}\int_0^t({\rm e}^{2\delta_0\kappa \tau}\mathcal{D}_{\theta,0}+\mathcal{D}_{\theta,\neq})(\tau){\rm d}\tau.
