\begin{rem}
   Because the Poiseuille flow is more complex than the couette flow, we have to deal with more nonlinear terms in the process of constructing energy estimation, and it is also difficult to utilize the multiplier theory. 
   Therefore, we need to put forward more requirements for the initial values. For example, from \eqref{2.16}--\eqref{2.17}, we can konw that the estimation of $u_0^1$ is essential. In addition, we will also need to use the estimates of $y{\partial}_y\theta_0$ and $y{\partial}_y\omega_0$, see \eqref{i51} for instance.

\end{rem}

\label{l4.1}
If $(\omega,\theta)(t,x,y)$ solves \eqref{4.1}, we have the following balances:
  \begin{equation}\label{4.2}
  \frac12{\frac{{\rm d}}{{\rm d} t}} \|\theta_k\|^2 +\mu\|\nabla_k\theta_k\|^2=-\mathfrak{R}\langle\theta_k,(u\cdot \nabla \theta)_k\rangle,
  \end{equation}
  \begin{equation}\label{4.3}
  \frac12{\frac{{\rm d}}{{\rm d} t}} \|{\partial}_y\theta_k\|^2 +\mu\|{\partial}_y\nabla_k\theta_k\|^2+2\mathfrak{R}\langle{\partial}_y\theta_k, iky\theta_k\rangle=-\mathfrak{R}\langle{\partial}_y\theta_k,{\partial}_y(u\cdot \nabla \theta)_k\rangle,
  \end{equation}
  \begin{align}\label{4.4}
  &{\frac{{\rm d}}{{\rm d} t}}\mathfrak{R}\langle iky \theta_k,{\partial}_y\theta_k\rangle+2|k|^2\| y\theta_k\|^2 \notag\\
  =&-2\mu\mathfrak{R}\langle iky{\partial}_{y}\theta_k, \Delta_k \theta_k\rangle+2\mathfrak{R}\langle iky{\partial}_{y}\theta_k, (u\cdot \nabla \theta)_k\rangle+\mathfrak{R}\langle ik\theta_k, (u\cdot \nabla \theta)_k\rangle,
  \end{align}
  \begin{equation}\label{4.5}
  \frac12{\frac{{\rm d}}{{\rm d} t}}\| y\theta_k\|^2+\mu\|y\nabla_k\theta_k\|^2=\mu\|\theta_k\|^2-\mathfrak{R}\langle y^2\theta_k, (u\cdot \nabla \theta)_k\rangle.
  \end{equation}

\label{l4.2}
	Let $(\omega_k,\theta_k)(t,x,y)$ solve \eqref{4.1}. Then we have the following balances:
 \begin{equation}\label{4.46}
  \frac12{\frac{{\rm d}}{{\rm d} t}} \|\omega_k\|^2 +\nu\|\nabla_k\omega_k\|^2=\mathfrak{R}\langle\omega_k,ik\theta_k-(u\cdot \nabla \omega)_k\rangle,
  \end{equation}
  \begin{equation}\label{4.47}
  \frac12{\frac{{\rm d}}{{\rm d} t}} \|{\partial}_y\omega_k\|^2 +\nu\|{\partial}_y\nabla_k\omega_k\|^2+2\mathfrak{R}\langle{\partial}_y\omega_k, iky\omega_k\rangle=\mathfrak{R}\langle{\partial}_y\omega_k,ik{\partial}_{y}\theta_k-{\partial}_y(u\cdot \nabla \omega)_k\rangle,
  \end{equation}
  \begin{align}\label{4.48}
  &{\frac{{\rm d}}{{\rm d} t}}\mathfrak{R}\langle iky \omega_k,{\partial}_y\omega_k\rangle+2|k|^2\| y\omega_k\|^2+4|k|^2\|{\partial}_{y}\phi_k\|^2 \notag\\
  =&-2\nu\mathfrak{R}\langle iky{\partial}_{y}\omega_k, \Delta_k \omega_k\rangle-2\mathfrak{R}\langle iky{\partial}_{y}\omega_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle-\mathfrak{R}\langle ik\omega_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle,
  \end{align}
  \begin{equation}\label{4.49}
  \frac12{\frac{{\rm d}}{{\rm d} t}}\| y\omega_k\|^2+\nu\|y\nabla_k\omega_k\|^2=\nu\|\omega_k\|^2-4\mathfrak{R}\langle y{\partial}_{y} \phi_k, ik\phi_k\rangle+\mathfrak{R}\langle y^2\omega_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle,
  \end{equation}
  \begin{equation}\label{4.50}
  \frac12{\frac{{\rm d}}{{\rm d} t}}\| \nabla_k \phi_k\|^2 +\nu\|\omega_k\|^2=2\mathfrak{R}\langle y{\partial}_{y} \phi_k,ik\phi_k\rangle-\mathfrak{R}\langle \phi_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle.
 \end{equation}

Taking the inner product of system \eqref{4.1}$_1$ with $\omega_k$ and $-{\partial}_{yy}\omega_k$ in $L^2$ respectively, and integrating the resulting equation by parts, we can obtain \eqref{4.46}--\eqref{4.47}. 

Turning to \eqref{4.48}, we use \eqref{4.1}$_1$ to compute
\begin{align}
{\frac{{\rm d}}{{\rm d} t}}\mathfrak{R}\langle iky\omega_k,{\partial}_y\omega_k\rangle=&\mathfrak{R}\langle iky{\partial}_{t} \omega_k,{\partial}_y\omega_k\rangle+\mathfrak{R}\langle iky\omega_k,{\partial}_{yt}\omega_k\rangle=-2\mathfrak{R}\langle iky{\partial}_{y}\omega_k,{\partial}_{t} \omega_k\rangle-\mathfrak{R}\langle ik\omega_k,{\partial}_{t}\omega_k\rangle\notag\\ 
=&\mathfrak{R}\langle 2iky{\partial}_{y}\omega_k+ik\omega_k, iky^2\omega_k -2ik\phi_k-\nu \Delta_k\omega_k+(u\cdot \nabla \omega)_k-ik\theta_k\rangle   \notag\\
=&-\nu\mathfrak{R}\langle 2iky{\partial}_{y}\omega_k+ik\omega_k, \Delta_k \omega_k\rangle+\mathfrak{R}\langle 2iky{\partial}_{y}\omega_k+ik\omega_k,(u\cdot \nabla \omega)_k-ik\theta_k\rangle   \notag\\
&+\mathfrak{R}\langle 2iky{\partial}_{y}\omega_k+ik\omega_k, iky^2\omega_k -2ik\phi_k\rangle .
\end{align}
For the second term, we can compute
\begin{align}
\mathfrak{R}\langle 2iky{\partial}_{y}\omega_k+ik\omega_k, iky^2\omega_k\rangle=2\mathfrak{R}\langle iky^3{\partial}_{y}\omega_k, ik\omega_k\rangle+\mathfrak{R}\langle ik\omega_k, iky^2\omega_k\rangle=-2|k|^2\| y\omega_k\|^2.\notag	
\end{align}
Lastly, the third term can be estimate as
\begin{align}
-2\mathfrak{R}\langle 2iky{\partial}_{y}\omega_k+ik\omega_k, ik\phi_k\rangle=&-4|k|^2\mathfrak{R}\langle y{\partial}_{y}\omega_k, \phi_k\rangle-2|k|^2\mathfrak{R}\langle \omega_k, \phi_k\rangle	\notag\\ 
=&-2|k|^2\mathfrak{R}\langle y{\partial}_{y}\omega_k, \phi_k\rangle+2|k|^2\mathfrak{R}\langle y\omega_k, {\partial}_{y}\phi_k\rangle\notag\\ 
=&-2|k|^2\mathfrak{R}\langle {\partial}_y\Delta_k\phi_k,y\phi_k\rangle+2|k|^2\mathfrak{R}\langle y\Delta_k\phi_k,{\partial}_{y}\phi_k\rangle\notag \\  
=&2|k|^2\mathfrak{R}\langle y\Delta_k\phi_k,{\partial}_{y}\phi_k\rangle-2|k|^2\mathfrak{R}\langle \Delta_k(y\phi_k),{\partial}_{y}\phi_k\rangle=-4|k|^2\| {\partial}_{y}\phi_k\|^2,\notag
\end{align}
and then \eqref{4.48} follows. For \eqref{4.49}, we have
\begin{align}
\frac12{\frac{{\rm d}}{{\rm d} t}}\| y\omega_k\|^2
&=\mathfrak{R}\langle y\omega_k, y(2ik\phi_k+\nu\Delta_k \omega_k-iky^2\omega_k +ik\theta_k-(u\cdot \nabla \omega)_k)\rangle\notag\\
&=2\langle y\Delta\phi_k,iky\phi_k\rangle+\nu\langle y\omega_k, y \Delta_k \omega_k\rangle +\mathfrak{R}\langle y\omega_k, y(ik\theta_k-(u\cdot \nabla \omega)_k)\rangle \notag\\
&=\nu\|\omega_k\|^2-\nu\|y\nabla_k\omega_k\|^2-4\mathfrak{R}\langle y{\partial}_{y}\phi_k,ik\phi_k\rangle+\mathfrak{R}\langle y^2\omega_k,ik\theta_k-(u\cdot \nabla \omega)_k)\rangle.\notag
 \end{align}
For \eqref{4.50}, we multiply \eqref{4.1}$_1$ by $-\phi_k$ and integrate it to obtain
\begin{align}
-\langle{\partial}_t\omega_k,\phi_k\rangle -\langle iky^2\omega_k,\phi_k\rangle =-\langle\nu\Delta_k\omega_k+ik\theta_k-(u\cdot \nabla \omega)_k,\phi_k\rangle.\notag
\end{align}
Notice that
\begin{align}
 -\langle iky^2\Delta_k \phi_k,\phi_k\rangle=2\langle iky{\partial}_{y} \phi_k,\phi_k\rangle+\langle iky^2\nabla_k \phi_k,\nabla_k\phi_k\rangle=2\langle iky {\partial}_{y} \phi_k,\phi_k\rangle,\notag
\end{align}
hence we have \eqref{4.50}.
The proof of Lemma \ref{l4.2} is over.

We firstly observe that 
\begin{equation}\notag
 \langle {\partial}_{y}\phi_k, y\omega_k \rangle=\langle {\partial}_{y}\phi_k, y{\partial}_{yy}\phi_k \rangle-\langle {\partial}_{y}\phi_k, y|k|^2\phi_k \rangle=-\frac12\|{\partial}_{y}\phi_k\|^2+\frac12|k|^2\|\phi_k\|^2,
\end{equation}
then it follows that
\begin{align}\label{4.59}
|k|^2\|\phi_k\|^2=\|{\partial}_{y}\phi_k\|^2+2\langle{\partial}_{y}\phi_k, y\omega_k \rangle\leq 2\|{\partial}_{y}\phi_k\|^2+\|y\omega_k\|^2.
\end{align}
According to the energy estimation in Lemma \ref{l4.2}, \eqref{4.59} and the definition of $E_{\omega}[\omega_k]$ in \eqref{2.6}, one can verify that the following inequality holds
\begin{align}\label{4.60}
&{\frac{{\rm d}}{{\rm d} t}} E_{\omega}[\omega_k] +\nu\|\nabla_k\omega_k\|^2+\nu^{\frac32}|k|^{-\frac12}\|{\partial}_y\nabla_k\omega_k\|^2+4|k|\| y\omega_k\|^2+|k|\|\nabla_k\phi_k\|^2\notag\\ 
&\qquad+100\nu^{\frac12}|k|^{\frac12}\left(\|y\nabla_k\omega_k\|^2 +\|\omega_k\|^2\right)\notag\\
\leq&-2\nu^{\frac12}|k|^{-\frac12}\mathfrak{R}\langle iky\omega_k,{\partial}_y\omega_k\rangle-5\nu|k|^{-1}\mathfrak{R}\langle \Delta_k \omega_k, iky{\partial}_{y}\omega_k\rangle+\mathfrak{R}\langle\omega_k,ik\theta_k-(u\cdot \nabla \omega)_k\rangle\notag\\ 
&+\nu^{\frac12}|k|^{-\frac12}\mathfrak{R}\langle{\partial}_y\omega_k,ik{\partial}_{y}\theta_k-{\partial}_y(u\cdot \nabla \omega)_k\rangle-5|k|^{-1}\mathfrak{R}\langle iky{\partial}_{y}\omega_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle\notag\\ 
&-\frac52|k|^{-1}\mathfrak{R}\langle ik\omega_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle+100\nu^{-\frac12}|k|^{\frac12}\mathfrak{R}\langle y^2\omega_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle\notag\\ 
&-200\nu^{-\frac12}|k|^{\frac12}\mathfrak{R}\langle \phi_k, ik\theta_k-(u\cdot \nabla \omega)_k\rangle.
\end{align}

We first handle the first two terms on the right-hand side. Using Young inequality, we obtain
\begin{align}\label{4.61}
-2\nu^{\frac12}|k|^{-\frac12}\mathfrak{R}\langle iky\omega_k,{\partial}_y\omega_k\rangle\leq \frac{\nu}{2} \|\nabla_k \omega_k\|^2+ 2|k|\|y\omega_k\|^2,
\end{align}
\begin{align}\label{4.62}
-5\nu|k|^{-1}\mathfrak{R}\langle \Delta_k \omega_k, iky{\partial}_{y}\omega_k\rangle=&5\nu|k|^{-1}\mathfrak{R}\langle y|k|^2 \omega_k, ik{\partial}_{y}\omega_k\rangle-5\nu|k|^{-1}\mathfrak{R}\langle {\partial}_{yy} \omega_k, iky{\partial}_{y}\omega_k\rangle\notag\\ 
\leq& 5\nu|k|^{2}\|y\omega_k\|\|{\partial}_{y}\omega_k\|+5\nu\|{\partial}_{yy} \omega_k\|\|y{\partial}_{y}\omega_k\| \notag\\ 
\leq&10\nu\|{\partial}_{y} \nabla_k\omega_k\|\|y\nabla_k\omega_k\|  \notag\\
\leq&\frac{1}{2}\nu^{\frac32}|k|^{-\frac12}\|{\partial}_{y} \nabla_k\omega_k\|^2  +50\nu^{\frac12}|k|^{\frac12}\|y\nabla_k\omega_k\|^2.
\end{align}
Then, substituting \eqref{4.61}--\eqref{4.62} into \eqref{4.60}, and multiplying both sides of the resulting equation by ${\rm e}^{2\delta_0 \kappa^{\frac12}t}$, after performing some integration by parts, we arrive at
\begin{align}\label{4.63}
&{\frac{{\rm d}}{{\rm d} t}} \mathcal{E}_{\omega,\neq} +\frac12\mathcal{D}_{\omega,\neq}-2\delta_0\kappa^{\frac12 }\mathcal{E}_{\omega,\neq}\notag\\
\leq&{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m}\mathfrak{R}\langle\omega_k,ik\theta_k\rangle+\nu^{\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m-\frac12}\mathfrak{R}\langle{\partial}_y\omega_k,ik{\partial}_{y}\theta_k\rangle\notag\\ 
&-5{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m-1}\mathfrak{R}\langle iky{\partial}_{y}\omega_k, ik\theta_k\rangle-\frac52{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m-1}\mathfrak{R}\langle ik\omega_k, ik\theta_k\rangle\notag\\ 
&+100\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12}\mathfrak{R}\langle y^2\omega_k, ik\theta_k\rangle-200\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12}\mathfrak{R}\langle \phi_k, ik\theta_k\rangle\notag\\ 
&-{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m}\mathfrak{R}\langle\omega_k,(u\cdot \nabla \omega)_k\rangle-\nu^{\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m-\frac12}\mathfrak{R}\langle{\partial}_y\omega_k,{\partial}_y(u\cdot \nabla \omega)_k\rangle\notag\\ 
&+5{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m-1}\mathfrak{R}\langle iky{\partial}_{y}\omega_k, (u\cdot \nabla \omega)_k\rangle+\frac52{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m-1}\mathfrak{R}\langle ik\omega_k, (u\cdot \nabla \omega)_k\rangle\notag\\ 
&-100\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12}\mathfrak{R}\langle y^2\omega_k, (u\cdot \nabla \omega)_k\rangle\notag\\ 
&+200\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12}\mathfrak{R}\langle \phi_k, (u\cdot \nabla \omega)_k\rangle:=\sum_{i=1}^{12}J_i.
\end{align}
First of all, it is easy to check that if $\delta_0\leq 2^{-16}$, 
\begin{equation}\label{4.64}
	2\delta_0\kappa^{\frac12 }\mathcal{E}_{\omega,\neq}\leq \frac{1}{16}\mathcal{D}_{\omega,\neq}.
\end{equation}
Next, using H\"older inequality, Young inequality and definitions \eqref{2.2}--\eqref{2.13} yields
\begin{align}\label{4.65}
	\sum_{i=1}^{4}J_i\leq&\frac72{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+1}\|\omega_k\|\|\theta_k\|+\nu^{\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12}\|{\partial}_{yy}\omega_k\|\|\theta_k\|\notag\\ 
&+5{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+1}\|y{\partial}_{y}\omega_k\|\|\theta_k\|\notag\\
\leq&\frac72\nu^{-\frac14}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}(\nu^{\frac14}|k|^{m+\frac14}\|\omega_k\|)(|k|^{m+\frac34}\|\theta_k\|)\notag\\ 
&+\nu^{-\frac14}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}(\nu^{\frac34}|k|^{m-\frac14}\|{\partial}_{yy}\omega_k\|)(|k|^{m+\frac34}\|\theta_k\|)\notag\\ 
&+5\nu^{-\frac14}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}(\nu^{\frac14}|k|^{m+\frac14}\|y{\partial}_{y}\omega_k\|)(|k|^{m+\frac34}\|\theta_k\|)\notag\\
\leq& \frac{1}{16}\mathcal{D}_{\omega,\neq}+C_1\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}(|k|^{2m+\frac12}\|\theta_k\|^2)^{\frac13}(|k|^{2m+2}\|\theta_k\|^2)^{\frac23}\notag\\
\leq& \frac{1}{16}\mathcal{D}_{\omega,\neq}+C_1\nu^{-\frac12}\mu^{-\frac56}\mathcal{D}_{\theta,\neq},
\end{align}
\begin{align}\label{4.66}
J_5+J_6\leq& 100\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac32}\|y\omega_k\|\|y\theta_k\|+200\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac32}\|\phi_k\|\|\theta_k\|\notag\\ 
\leq&100\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}(|k|^{m+\frac12}\|y\omega_k\|)(|k|^{m+1}\|y\theta_k\|)\notag\\ 
&+200\nu^{-\frac12}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}(|k|^{m+\frac32}\|\phi_k\|)(|k|^{m}\|\theta_k\|)\notag\\
\leq& \frac{1}{16}\mathcal{D}_{\omega,\neq}+C_2\nu^{-1}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\left(\sum_{k \neq 0}(|k|^{2m+1}\|y\theta_k\|^2)^{\frac13}(|k|^{2m+\frac52}\|y\theta_k\|^2)^{\frac23}+\sum_{k \neq 0}|k|^{2m}\|\theta_k\|^2\right)\notag\\
\leq& \frac{1}{16}\mathcal{D}_{\omega,\neq}+C_2\nu^{-1}\mu^{-\frac12}\mathcal{D}_{\theta,\neq}.	
\end{align}

Similar to \eqref{i1}, \eqref{i2}, \eqref{i3}, \eqref{i4} and \eqref{i5}, we can estimate $J_7$--$J_{11}$ as
\begin{align}\label{j7}
       J_7\lesssim\nu^{-\frac{1}{2}} \mathcal{E}^{\frac{1}{2}}_{\omega,\neq} \mathcal{D}^{\frac{1}{2}}_{\omega, \neq}\mathcal{D}^{\frac{1}{2}}_{\omega, 0}+\nu^{-\frac{2}{3}}\mathcal{E}^{\frac{1}{2}}_{\omega,\neq} \mathcal{D}_{\omega,\neq},
\end{align}
\begin{align}\label{j8}
       J_8\lesssim& \nu^{-\frac12}\mathcal{E}_{\omega,0}^{\frac12}\mathcal{D}_{\omega,\neq}+\nu^{-\frac{13}{24}}\mathcal{E}_{\omega,\neq}^{\frac12}\mathcal{D}_{\omega,\neq},
\end{align}
\begin{align}\label{j9}
       J_9\lesssim& \nu^{-\frac{2}{3}}\|u_{0}\|_{L^\infty}\mathcal{D}_{\omega,\neq}+\nu^{\frac{1}{4}}\nu^{-\frac{3}{4}} \mathcal{E}^{\frac{1}{2}}_{\omega,\neq} \mathcal{D}^{\frac{1}{2}}_{\omega, \neq}\mathcal{D}^{\frac{1}{2}}_{\omega, 0}+\nu^{-\frac34}\mathcal{E}_{\omega,\neq}^{\frac12}\mathcal{D}_{\omega,\neq},
\end{align}
\begin{align}\label{j10}
      J_{10}\lesssim& \nu^{-\frac{2}{3}}\|u_{0}\|_{L^\infty}\mathcal{D}_{\omega,\neq}+\nu^{-\frac{1}{2}} \mathcal{E}^{\frac{1}{2}}_{\omega, 0} \mathcal{D}_{\omega, \neq}+\nu^{-\frac34}\mathcal{E}_{\omega,\neq}^{\frac12}\mathcal{D}_{\omega,\neq},
\end{align}
\begin{align}\label{j11}
       J_{11}\lesssim&\nu^{-\frac{1}{2}}\mathcal{E}^{\frac{1}{2}}_{\omega,0} \mathcal{D}_{\omega, \neq}+\nu^{-\frac34}\mathcal{E}_{\omega,\neq}^{\frac12}\mathcal{D}_{\omega,\neq}.
\end{align}
For $J_{12}$, we can prove 
\begin{align}\label{j12}
J_{12}=&200\nu^{-\frac{1}{2}}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12}\mathfrak{R}\langle \phi_k, -\sum_{l \in \mathbb{Z}} \partial_y \phi_{k-l} \cdot il  \omega_{l}+ \sum_{l \in \mathbb{Z}} i(k-l)\phi_{k-l} \cdot \partial_{y} \omega_{l}  \rangle\notag\\
=&-200\nu^{-\frac{1}{2}}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12} \mathfrak{R}\langle \phi_k, \partial_{y} \phi_{0} \cdot ik \omega_k \rangle \notag\\ 
&+200\nu^{-\frac{1}{2}}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}|k|^{2m+\frac12} \mathfrak{R}\langle \phi_k,  ik \phi_{k} \cdot  \partial_{y} \omega_0 \rangle\notag\\
&+200\nu^{-\frac{1}{2}}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{\substack{ k,l \neq 0 \\ k \neq l }} |k|^{2m+\frac12} \mathfrak{R}\langle \phi_k,  -\partial_y \phi_{k-l} \cdot il  \omega_{l}+ i(k-l)\phi_{k-l} \cdot \partial_{y} \omega_{l} \rangle\notag\\
\lesssim&\nu^{-\frac{1}{2}}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{k \neq 0}(|k|^{m+\frac32}\|\phi_k\|)(|k|^{m}\omega_k \|)\|\partial_{y} \phi_{0}\|_{L^\infty}\notag\\ 
&+\nu^{-\frac{1}{2}}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{\substack{ k,l \neq 0 \\ k \neq l }}(|k|^{m+\frac32}\|\phi_k\|)(\||l|^{m}\omega_l \|)\|\partial_{y} \phi_{k-l}\|_{L^\infty}\notag\\ 
&+\nu^{-\frac{1}{2}}{\rm e}^{2\delta_0 \kappa^{\frac12}t}\sum_{\substack{ k,l \neq 0 \\ k \neq l }}(|k|^{m+\frac34}\|\phi_k\|)\|\omega_l \|(|k-l|^{m+\frac34}\|\partial_{y} \phi_{k-l}\|_{L^\infty})\notag\\ 
\lesssim&\left(\nu^{-\frac34}\|u_{0}\|_{L^\infty}\mathcal{D}_{\omega,\neq}^{\frac12}+\nu^{-\frac{1}{2}}{\rm e}^{\delta_0 \kappa^{\frac12}t}\mathcal{E}_{\omega,\neq}^{\frac12}\left(\sum_{\substack{ k \neq 0 }}|k|^{2m}\|\partial_{y} \phi_{k}\|\|\partial_{yy} \phi_{k}\|\right)^{\frac12}\right)\left(\sum_{\substack{ k \neq 0 }}|k|^{2m+3}\|\phi_{k}\|^2\right)^{\frac12}\notag\\ 
&+\nu^{-\frac{1}{2}}{\rm e}^{\delta_0 \kappa^{\frac12}t}\mathcal{E}_{\omega,\neq}^{\frac12}\left(\sum_{\substack{ k \neq 0 }}|k|^{2m+\frac32}\|\phi_{k}\|^2\right)^{\frac12}\left(\sum_{\substack{ k \neq 0 }}|k|^{2m+\frac32}\|\partial_{y} \phi_{k}\|\|\partial_{yy} \phi_{k}\|\right)^{\frac12}\notag\\ 
 \lesssim&\nu^{-\frac34}\|u_{0}\|_{L^\infty}\mathcal{D}_{\omega,\neq}+\nu^{-\frac34}\mathcal{E}_{\omega,\neq}^{\frac12}\mathcal{D}_{\omega,\neq}.      
\end{align}	
Putting \eqref{4.64}--\eqref{j12} into \eqref{4.63} gives \eqref{2.16}.


Thus,we have completed the proof of Propositions \ref{p2} and \ref{p4}.


